func (c *Codec) EncodeAttestedTopics(
	evt abi.Event,
	values []AttestedTopics,
) ([]*evm.TopicValues, error) {
	var keyRule []interface{}
	for _, v := range values {
		if reflect.ValueOf(v.Key).IsZero() {
			keyRule = append(keyRule, common.Hash{})
			continue
		}
		fieldVal, err := bindings.PrepareTopicArg(evt.Inputs[0], v.Key)
		if err != nil {
			return nil, err
		}
		keyRule = append(keyRule, fieldVal)
	}
	var nullifierRule []interface{}
	for _, v := range values {
		if reflect.ValueOf(v.Nullifier).IsZero() {
			nullifierRule = append(nullifierRule, common.Hash{})
			continue
		}
		fieldVal, err := bindings.PrepareTopicArg(evt.Inputs[1], v.Nullifier)
		if err != nil {
			return nil, err
		}
		nullifierRule = append(nullifierRule, fieldVal)
	}

	rawTopics, err := abi.MakeTopics(
		keyRule,
		nullifierRule,
	)
	if err != nil {
		return nil, err
	}

	return bindings.PrepareTopics(rawTopics, evt.ID.Bytes()), nil
}

